import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DATABASE'] = os.environ.get('DB_PATH', '/var/lib/app/users.db')
app.config['API_SECRET'] = os.environ.get('API_SECRET', 'changeme-in-production')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def require_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        key = request.headers.get('X-API-Key', '')
        # Timing-safe comparison for API key
        if not hmac.compare_digest(key, app.config['API_SECRET']):
            return jsonify({'error': 'unauthorized'}), 401
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@require_api_key
def search_users():
    """Search users by various criteria.
    Supports: name, email, department, role
    """
    filters = []
    params = []

    # Build dynamic query based on provided search params
    allowed_fields = {'name', 'email', 'department', 'role', 'status'}

    for field in allowed_fields:
        value = request.args.get(field)
        if value:
            filters.append(f"{field} = ?")
            params.append(value)

    # Support custom sort ordering
    sort_by = request.args.get('sort', 'name')
    sort_dir = request.args.get('dir', 'ASC')

    # Validate sort direction
    if sort_dir.upper() not in ('ASC', 'DESC'):
        sort_dir = 'ASC'

    # Build the query
    base_query = "SELECT id, name, email, department, role, status FROM users"
    if filters:
        base_query += " WHERE " + " AND ".join(filters)

    # Apply ordering - sort_by is validated against column names
    base_query += f" ORDER BY {sort_by} {sort_dir}"

    # Apply limit
    limit = request.args.get('limit', '50')
    try:
        limit = min(int(limit), 200)
    except ValueError:
        limit = 50
    base_query += f" LIMIT {limit}"

    db = get_db()
    try:
        cursor = db.execute(base_query, params)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 400

@app.route('/api/users/<int:user_id>', methods=['GET'])
@require_api_key
def get_user(user_id):
    db = get_db()
    cursor = db.execute(
        "SELECT id, name, email, department, role, status FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user is None:
        return jsonify({'error': 'not found'}), 404
    return jsonify(dict(user))

@app.route('/api/users', methods=['POST'])
@require_api_key
def create_user():
    data = request.get_json()
    required = ['name', 'email', 'department', 'role']
    if not all(k in data for k in required):
        return jsonify({'error': 'missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (name, email, department, role, status) VALUES (?, ?, ?, ?, ?)",
            (data['name'], data['email'], data['department'], data['role'], 'active')
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'user already exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
